create or replace function public.set_organisation_member_assignments(target_membership uuid,target_branch_ids uuid[],target_warehouse_ids uuid[],target_project_ids uuid[],target_approval_limit numeric,target_reason text) returns void language plpgsql security definer set search_path=public as $$
declare m public.organisation_members;target_scope text;assignment uuid;before_value jsonb;
begin select * into m from organisation_members where id=target_membership for update;if m.id is null then raise exception 'Membership not found';end if;target_scope:=organisation_scope(m.organisation_id);if not has_permission(organisation_manage_permission(target_scope),m.organisation_id)then raise exception 'Not authorised';end if;if length(trim(coalesce(target_reason,'')))<5 then raise exception 'A detailed reason is required';end if;if target_approval_limit is not null and target_approval_limit<0 then raise exception 'Approval limit cannot be negative';end if;if exists(select 1 from supplier_branches where id=any(coalesce(target_branch_ids,'{}'))and organisation_id<>m.organisation_id)then raise exception 'Branch belongs to another organisation';end if;if exists(select 1 from supplier_warehouses where id=any(coalesce(target_warehouse_ids,'{}'))and organisation_id<>m.organisation_id)then raise exception 'Warehouse belongs to another organisation';end if;if exists(select 1 from projects where id=any(coalesce(target_project_ids,'{}'))and organisation_id<>m.organisation_id)then raise exception 'Project belongs to another organisation';end if;select jsonb_build_object('branches',(select coalesce(jsonb_agg(branch_id),'[]')from branch_memberships where membership_id=m.id),'warehouses',(select coalesce(jsonb_agg(warehouse_id),'[]')from warehouse_memberships where membership_id=m.id),'projects',(select coalesce(jsonb_agg(project_id),'[]')from project_memberships where membership_id=m.id))into before_value;delete from branch_memberships where membership_id=m.id;delete from warehouse_memberships where membership_id=m.id;delete from project_memberships where membership_id=m.id;foreach assignment in array coalesce(target_branch_ids,'{}')loop insert into branch_memberships values(m.id,assignment,auth.uid(),now());end loop;foreach assignment in array coalesce(target_warehouse_ids,'{}')loop insert into warehouse_memberships values(m.id,assignment,auth.uid(),now());end loop;foreach assignment in array coalesce(target_project_ids,'{}')loop insert into project_memberships values(m.id,assignment,target_approval_limit,auth.uid(),now());end loop;insert into membership_audit_log(actor_id,scope,target_membership_id,target_user_id,organisation_id,action,reason,before_data,after_data)values(auth.uid(),target_scope,m.id,m.user_id,m.organisation_id,'assignments_changed',trim(target_reason),before_value,jsonb_build_object('branches',coalesce(target_branch_ids,'{}'),'warehouses',coalesce(target_warehouse_ids,'{}'),'projects',coalesce(target_project_ids,'{}'),'approval_limit',target_approval_limit));end;$$;
revoke all on function public.set_organisation_member_assignments(uuid,uuid[],uuid[],uuid[],numeric,text)from public,anon;grant execute on function public.set_organisation_member_assignments(uuid,uuid[],uuid[],uuid[],numeric,text)to authenticated;
